package com.vstream.Vidiserver;

/** The sign-in helpers served at /mq-auth.js (remember me, Google) (made from mq-auth.js by the update script - do not edit by hand). */
final class AuthJs {

    private AuthJs() {
    }

    static final String JS = ""
            + "// Memoryq sign-in helpers for every page: where the sign-in is kept (\"remember me for 30 days\" or only until the browser\n"
            + "// closes) and the \"Sign in with Google\" button. Served at /mq-auth.js.\n"
            + "(function () {\n"
            + "  'use strict';\n"
            + "  var A = {};\n"
            + "  var cfg = null;\n"
            + "  A.token = function () {\n"
            + "    try { return localStorage.getItem('vs_token') || sessionStorage.getItem('vs_token'); } catch (e) { return null; }\n"
            + "  };\n"
            + "  /** remember = true: kept on this device (30 days); false: only until the browser is closed. */\n"
            + "  A.save = function (token, remember) {\n"
            + "    try {\n"
            + "      localStorage.removeItem('vs_token'); sessionStorage.removeItem('vs_token');\n"
            + "      (remember === false ? sessionStorage : localStorage).setItem('vs_token', token);\n"
            + "      localStorage.setItem('mq_remember', remember === false ? '0' : '1');\n"
            + "    } catch (e) { }\n"
            + "  };\n"
            + "  A.clear = function () { try { localStorage.removeItem('vs_token'); sessionStorage.removeItem('vs_token'); } catch (e) { } };\n"
            + "  /** The last choice of the \"remember me\" box on this device (ticked the first time). */\n"
            + "  A.rememberDefault = function () { try { return localStorage.getItem('mq_remember') !== '0'; } catch (e) { return true; } };\n"
            + "  /** Phone apps' built-in browsers: Google does not allow its sign-in there. */\n"
            + "  A.inApp = /; wv\\)|Memoryq-App|Vstream/i.test(navigator.userAgent || '');\n"
            + "  A.config = function () {\n"
            + "    if (cfg) { return Promise.resolve(cfg); }\n"
            + "    return fetch('/api/auth/config').then(function (r) { return r.json(); }).then(function (d) { cfg = d || {}; return cfg; })\n"
            + "      .catch(function () { cfg = {}; return cfg; });\n"
            + "  };\n"
            + "  function post(path, form) {\n"
            + "    var h = { 'Content-Type': 'application/x-www-form-urlencoded' };\n"
            + "    var t = A.token();\n"
            + "    if (t) { h.Authorization = 'Bearer ' + t; }\n"
            + "    return fetch(path, { method: 'POST', headers: h, body: new URLSearchParams(form).toString() })\n"
            + "      .then(function (r) { return r.json().catch(function () { return {}; }).then(function (d) { return { ok: r.ok, status: r.status, data: d }; }); })\n"
            + "      .catch(function () { return { ok: false, status: 0, data: { error: 'Cannot reach the server' } }; });\n"
            + "  }\n"
            + "  A.post = post;\n"
            + "  var gisLoading = null;\n"
            + "  function loadGis() {\n"
            + "    if (window.google && window.google.accounts && window.google.accounts.id) { return Promise.resolve(); }\n"
            + "    if (gisLoading) { return gisLoading; }\n"
            + "    gisLoading = new Promise(function (ok, fail) {\n"
            + "      var s = document.createElement('script');\n"
            + "      s.src = 'https://accounts.google.com/gsi/client'; s.async = true; s.onload = ok; s.onerror = fail;\n"
            + "      document.head.appendChild(s);\n"
            + "    });\n"
            + "    return gisLoading;\n"
            + "  }\n"
            + "  /**\n"
            + "   * Puts the \"Sign in with Google\" button into el. opts: remember() -> true/false, link (true: link Google to the account\n"
            + "   * signed in now), onDone(answer of the sign-in), onError(message). Hides el when Google sign-in is not set up.\n"
            + "   */\n"
            + "  A.google = function (el, opts) {\n"
            + "    if (!el) { return Promise.resolve(false); }\n"
            + "    opts = opts || {};\n"
            + "    return A.config().then(function (c) {\n"
            + "      if (!c.google || A.inApp) { el.hidden = true; return false; }\n"
            + "      return loadGis().then(function () {\n"
            + "        el.hidden = false;\n"
            + "        window.google.accounts.id.initialize({\n"
            + "          client_id: c.google, ux_mode: 'popup', auto_select: false, cancel_on_tap_outside: true,\n"
            + "          callback: function (resp) {\n"
            + "            var remember = opts.remember ? opts.remember() : true;\n"
            + "            post('/api/auth/google', { credential: resp.credential, remember: remember ? '1' : '0', link: opts.link ? '1' : '' }).then(function (r) {\n"
            + "              if (!r.ok) { if (opts.onError) { opts.onError(r.data.error || 'Google sign-in did not work'); } return; }\n"
            + "              if (r.data.token) { A.save(r.data.token, remember); }\n"
            + "              if (opts.onDone) { opts.onDone(r.data); }\n"
            + "            });\n"
            + "          }\n"
            + "        });\n"
            + "        el.textContent = '';\n"
            + "        window.google.accounts.id.renderButton(el, { theme: 'outline', size: 'large', shape: 'pill', text: opts.link ? 'continue_with' : 'signin_with',\n"
            + "          width: Math.min(360, Math.max(220, el.clientWidth || 300)) });\n"
            + "        return true;\n"
            + "      }).catch(function () { el.hidden = true; return false; });\n"
            + "    });\n"
            + "  };\n"
            + "  window.MQAuth = A;\n"
            + "})();\n";
}